/**
 * @file touch.ts
 * @input The gesture core: the arena, the recognizers and their geometry.
 *   Also the pan, the motion engine and math, and the touch-presentation,
 *   direction, focus and hit-area helpers that Lab components read
 * @output `@astryxdesign/core/internal/touch`: the gesture core's primitives
 *   and the motion, touch-presentation, direction, focus and hit-area
 *   modules for Lab components, re-exported by name
 * @position An internal entry reserved for Astryx's own packages:
 *   undocumented, outside the public API and its compatibility promise
 *   (spec:AST-017 FR21), versioned in lockstep with Core, and allowed only in
 *   Core and Lab by the `@astryx/no-core-internal-import` lint rule
 *   (architecture:react-component-runtime INV13). Core components import the
 *   same modules by relative path. Named re-exports only, never a gathering
 *   object: a bundler keeps one copy per page and only what a component uses
 *   (architecture:component-style-authoring INV6). Importing it attaches no
 *   listeners: a recognizer listens only once a component starts it under a
 *   coarse pointer (`spec:AST-094` FR19, FR24).
 *
 * SYNC: When modified, update scripts/touch-support-bundle.test.mjs and
 * touch.test.ts.
 */

export { browserClock, GestureArena } from "../gestures/GestureArena.js";
export { ALL_NATIVE_TOUCH, GestureRecognizer, isActive, isTerminal, isTransitionAllowed, MANIPULATION } from "../gestures/GestureRecognizer.js";
export { angleBetween, centroid, distance, travel, unwrapAngle } from "../gestures/geometry.js";
export { LongPressGestureRecognizer } from "../gestures/LongPressGestureRecognizer.js";
export { TapGestureRecognizer } from "../gestures/TapGestureRecognizer.js";
export { DEFAULT_ENVIRONMENT } from "../gestures/types.js";

// Lab's useRefreshControl reads these: its pull's pan and the hook that
// starts it. It also reads the motion engine and math, and the scroll
// view's bounce spring, for its pull, settle and end. Its indicator fades
// along the settle's curve, and the motion-role parsers read the theme's
// tokens for its end.
export { PanGestureRecognizer } from "../gestures/PanGestureRecognizer.js";
export { useGestureRecognizer } from "../gestures/useGestureRecognizer.js";
// The motion engine's factory. The public one, `createAnimator`, plays
// only the theme's state-change motion.
export { createMotionEngine } from "../motion/animator.js";
export { cubicBezier } from "../motion/bezier.js";
export { mapProgress } from "../motion/progress.js";
export { parseCssEasing, parseMotionRoleValue } from "../motion/roles.js";
export { rubberBand, rubberBandInverse, rubberBandSlope } from "../motion/rubberBand.js";
export { scroll } from "../motion/uikit/scroll.js";

// Lab components also read the UIKit gesture table, the touch presentation
// and its query, and an element's direction.
export { isRtlElement } from "../hooks/isRtlElement.js";
export { UIKIT_GESTURES } from "../motion/uikit/gestures.js";
export { useTouchPresentation } from "../utils/touchPresentation.js";
export { TOUCH_QUERY } from "../utils/touchQueries.js";

// Lab's NavigationStack reads these.
export { ScreenEdgePanGestureRecognizer } from "../gestures/ScreenEdgePanGestureRecognizer.js";
export { resolveMotion } from "../motion/resolveMotion.js";
export { solveSpring, toSpring } from "../motion/spring.js";
export { navigation } from "../motion/uikit/navigation.js";
export { timing } from "../motion/uikit/timing.js";
export { NAVIGATION_BAR_ELEMENTS_SPRING, NAVIGATION_INTERACTIVE_POP_FINISH_SPRING, NAVIGATION_POP_SPRING, NAVIGATION_PUSH_SPRING } from "../motion/uikit/springs.js";
export { focusForLastInput, isFocusLost, prepareFocusReturnOnRemoval } from "../utils/focusReturn.js";
export { useInteractionModalityTracking } from "../utils/interactionModality.js";

// Lab components that watch a finger's scroll read whether a scroller's
// scroll is a finger's, and act when that scroll ends.
export { useFingerScroll } from "../gestures/useFingerScroll.js";
// Lab's NavigationStack scroll edge effect reads the finger-scroll hook
// above, and drops the veil's compositing layer when a finger's scroll ends.
// It reads the gesture host for a finger's landing. The stack's bars read the
// coarse-pointer check.
export { getGestureHost } from "../gestures/GestureHost.js";
export { isCoarsePointer } from "../utils/coarsePointer.js";
// Lab's PageControl also reads an element's shared animator, the Reduce
// Motion cross-fade, and the touch hit area's hook and layer.
export { animatorFor } from "../motion/animator.js";
export { reducedMotionFade } from "../motion/reducedMotion.js";
export { useTouchHitArea } from "../utils/touchHitArea.js";
export { touchHitAreaStyles } from "./touchHitArea.stylex.js";

// Lab's TabBar tracks its press with the shared action-group tracker.
export { useActionGroupTracking } from "../hooks/useActionGroupTracking.js";
// Lab's TabBar finds a panel's scroll area with Core's scroll test.
export { measureLogicalScrollAxis } from "../hooks/scrollGeometry.js";